def _check_dataset(name: str) -> dict[str, object]:
    dataset = load_dataset(name)
    schema_path = dataset.path / dataset.manifest.schema_ref.path
    schema = json.loads(schema_path.read_text(encoding="utf-8"))
    data_file = dataset.path / "data" / "train.jsonl"
    row_count = 0
    validation_errors = []
    for line_no, line in enumerate(data_file.read_text(encoding="utf-8").splitlines(), start=1):
        if not line.strip():
            continue
        row_count += 1
        row = json.loads(line)
        errors = validate_row(row, schema)
        if errors:
            validation_errors.append({"line": line_no, "errors": errors})
    row_index_count = len(read_row_index(name))
    return {
        "status": "ok",
        "dataset": name,
        "valid": not validation_errors,
        "row_count": row_count,
        "row_index_count": row_index_count,
        "validation_errors": validation_errors,
    }


def _publication_counts(state) -> dict[str, int]:
    counts: dict[str, int] = {}
    for entry in state.rows.values():
        counts[entry.status] = counts.get(entry.status, 0) + 1
    return counts


def _dataset_review_transition(
    name: str,
    row_ids: list[str],
    all_rows: bool,
    status: str,
    as_json: bool,
) -> None:
    try:
        current = evaluate_publication_state(name)
        selected = (
            list(current.rows)
            if all_rows
            else row_ids
        )
        if not selected:
            raise ValueError("provide at least one row_id or pass --all")
        state = set_publication_review_status(name, selected, status)
    except (FileNotFoundError, ValueError) as exc:
        click.echo(str(exc), err=True)
        sys.exit(3)
    payload = {
        "status": "ok",
        "dataset": name,
        "counts": _publication_counts(state),
        "row_ids": selected,
    }
    if as_json:
        click.echo(json.dumps(payload, indent=2, sort_keys=True))
        return
    click.echo(f"{name}: updated {len(selected)} row(s)")


def _load_row(root: Path, row_id: str) -> dict[str, object]:
    row_index = root / ".opentraces" / "row_index.jsonl"
    for line in row_index.read_text(encoding="utf-8").splitlines():
        if not line.strip():
            continue
        entry = json.loads(line)
        if entry.get("row_id") != row_id:
            continue
        data_file = root / entry["data_file"]
        data_line = data_file.read_text(encoding="utf-8").splitlines()[entry["line"] - 1]
        return json.loads(data_line)
    raise ValueError(f"row not found: {row_id}")

@dataset_group.command("review", cls=OpentracesCommand)
@click.argument("args", nargs=-1)
@click.option("--tui", "mode", flag_value="tui", default=None, help="Open TUI review.")
@click.option("--web", "mode", flag_value="web", help="Open web review.")
@click.option("--all", "all_rows", is_flag=True, help="With `reset`, reset every row to policy defaults.")
@click.option("--json", "as_json", is_flag=True, help="Emit structured JSON.")
def dataset_review(args: tuple[str, ...], mode: str | None, all_rows: bool, as_json: bool) -> None:
    """Review dataset rows, or reset selected rows to policy defaults."""
    if not args:
        click.echo("Usage: ot dataset review <name> OR ot dataset review reset <name> [ROW_ID...]", err=True)
        sys.exit(2)
    if args[0] == "reset":
        if len(args) < 2:
            click.echo("Usage: ot dataset review reset <name> [ROW_ID...]", err=True)
            sys.exit(2)
        _dataset_review_transition(args[1], list(args[2:]), all_rows, "reset", as_json)
        return
    if len(args) > 1:
        click.echo("Usage: ot dataset review <name>", err=True)
        sys.exit(2)
    name = args[0]
    try:
        state = evaluate_publication_state(name)
    except (FileNotFoundError, ValueError) as exc:
        click.echo(str(exc), err=True)
        sys.exit(3)
    payload = {
        "status": "ok",
        "dataset": name,
        "mode": mode or "cli",
        "counts": _publication_counts(state),
        "rows": {
            row_id: entry.model_dump(mode="json", exclude_none=True)
            for row_id, entry in sorted(state.rows.items())
        },
    }
    if as_json:
        click.echo(json.dumps(payload, indent=2, sort_keys=True))
        return
    click.echo(
        f"{name}: {payload['counts'].get('needs_review', 0)} rows need review, "
        f"{payload['counts'].get('publishable', 0)} publishable"
    )

# Bounded retry budget for ``publish_dataset`` parent_commit conflicts. Plan 058
# verification requires concurrent publishers to retry 412 conflicts without
# looping forever.
MAX_PARENT_COMMIT_RETRIES = 5


def datasets_dir() -> Path:
    return paths.OPENTRACES_DIR / "datasets"


def dataset_path(name: str) -> Path:
    return datasets_dir() / validate_dataset_name(name)


def validate_dataset_name(name: str) -> str:
    if not name or not _DATASET_NAME_RE.fullmatch(name):
        raise ValueError(
            "dataset name must start with a letter or number and contain only "
            "letters, numbers, '.', '_', or '-'"
        )
    return name


def create_dataset(
    name: str,
    *,
    description: str | None = None,
    workflow_skill: str | None = None,
    workflow_digest: str = "sha256:unconfigured",
    row_schema: dict[str, Any] | None = None,
    identity: DatasetIdentity | dict[str, Any] | None = None,
    publication_policy: DatasetPublicationPolicy | dict[str, Any] | None = None,
    replace: bool = False,
) -> LocalDataset:
    validate_dataset_name(name)
    root = dataset_path(name)
    if root.exists():
        if not replace:
            raise FileExistsError(f"dataset already exists: {name}")
        shutil.rmtree(root)

    schema_payload = row_schema or default_row_schema()
    identity_model = (
        identity
        if isinstance(identity, DatasetIdentity)
        else DatasetIdentity.model_validate(identity or {"mode": "payload_hash"})
    )
    policy_model = (
        publication_policy
        if isinstance(publication_policy, DatasetPublicationPolicy)
        else DatasetPublicationPolicy.model_validate(publication_policy or {})
    )
    workflow = WorkflowRef(
        skill=workflow_skill or f"{name}-workflow",
        digest=workflow_digest,
    )
    manifest = DatasetManifest(
        name=name,
        description=description,
        schema={"path": "schemas/row.schema.json", "version": "1.0.0"},
        workflow=workflow,
        identity=identity_model,
        publication_policy=policy_model,
    )
    schema_digest = digest_payload(schema_payload)
    manifest.schema_ref.digest = schema_digest

    (root / "schemas").mkdir(parents=True)
    (root / "data").mkdir()
    (root / ".opentraces" / "runs").mkdir(parents=True)
    write_json(root / "schemas" / "row.schema.json", schema_payload)
    (root / "data" / "train.jsonl").write_text("", encoding="utf-8")
    (root / ".opentraces" / "row_index.jsonl").write_text("", encoding="utf-8")
    (root / ".opentraces" / "cursors.yaml").write_text("queries: {}\n", encoding="utf-8")
    write_json(root / "dataset_infos.json", build_dataset_infos(name, schema_payload))
    (root / "README.md").write_text(
        build_dataset_card(name, description, manifest),
        encoding="utf-8",
    )
    save_manifest(root, manifest)
    return LocalDataset(name=name, path=root, manifest=manifest)


def load_manifest(root: Path | str) -> DatasetManifest:
    root = Path(root)
    manifest_path = root / ".opentraces" / "manifest.yaml"
    raw = yaml.safe_load(manifest_path.read_text(encoding="utf-8")) or {}
    return DatasetManifest.model_validate(raw)


def save_manifest(root: Path, manifest: DatasetManifest) -> None:
    manifest_path = root / ".opentraces" / "manifest.yaml"
    manifest_path.parent.mkdir(parents=True, exist_ok=True)
    data = manifest.model_dump(mode="json", by_alias=True, exclude_none=True)
    manifest_path.write_text(yaml.safe_dump(data, sort_keys=False), encoding="utf-8")


def list_datasets() -> list[LocalDataset]:
    root = datasets_dir()
    if not root.exists():
        return []
    datasets: list[LocalDataset] = []
    for item in sorted(root.iterdir(), key=lambda p: p.name):
        manifest_path = item / ".opentraces" / "manifest.yaml"
        if item.is_dir() and manifest_path.exists():
            datasets.append(LocalDataset(item.name, item, load_manifest(item)))
    return datasets

