@click.option("--resume", default=None, help="Resume a previous publication run id.")
@click.option("--json", "as_json", is_flag=True, help="Emit structured JSON.")
def dataset_publish(
    name: str,
    remote: str | None,
    check_only: bool,
    resume: str | None,
    as_json: bool,
) -> None:
    """Publish reviewed dataset rows and contract files to the active remote."""
    try:
        summary = publish_dataset(name, to=remote, check_only=check_only, resume=resume)
    except DatasetRemotePermissionError as exc:
        click.echo(str(exc), err=True)
        sys.exit(3)
    except DatasetRemoteSchemaAheadError as exc:
        click.echo(str(exc), err=True)
        sys.exit(3)
    except ValueError as exc:
        click.echo(str(exc), err=True)
        sys.exit(3)
    payload = {
        "status": "ok",
        "publish": {
            "dataset": summary.dataset_name,
            "remote": summary.remote_name,
            "repo_id": summary.repo_id,
            "run_id": summary.run_id,
            "uploaded": summary.uploaded,
            "check_only": summary.check_only,
            "new_row_count": summary.new_row_count,
            "duplicate_count": summary.duplicate_count,
            "needs_review_count": summary.needs_review_count,
            "blocked_count": summary.blocked_count,
            "staged_files": summary.staged_files,
            "remote_head_before": summary.remote_head_before,
            "remote_head_after": summary.remote_head_after,
            "attempts": summary.attempts,
            "message": summary.message,
        },
    }
    if as_json:
        click.echo(json.dumps(payload, indent=2, sort_keys=True))
        return
    click.echo(
        f"{summary.message}: rows={summary.new_row_count} "
        f"needs_review={summary.needs_review_count} blocked={summary.blocked_count}"
    )


def _clone_remote(
    remote: str,
    as_name: str | None,
    read_only: bool,
    with_data: bool,
    as_json: bool,
) -> None:
    try:
        dataset = clone_remote_dataset(remote, as_name=as_name, read_only=read_only)
    except (FileExistsError, FileNotFoundError, ValueError) as exc:
        click.echo(str(exc), err=True)
        sys.exit(3)
    pull_summary = None
    if with_data:
        try:
            pull_summary = pull_dataset(dataset.name, data=True)
        except (FileNotFoundError, ValueError) as exc:
            click.echo(str(exc), err=True)
            sys.exit(3)
    payload: dict[str, object] = {"status": "ok", "dataset": _dataset_payload(dataset)}
    if pull_summary is not None:
        payload["pull"] = {
            "imported_count": pull_summary.imported_count,
            "duplicate_count": pull_summary.duplicate_count,
        }
    if as_json:
        click.echo(json.dumps(payload, indent=2, sort_keys=True))
        return
    click.echo(f"Dataset cloned: {dataset.name}")
    if pull_summary is not None:
        click.echo(f"Pulled {pull_summary.imported_count} row(s)")


