    row = results[0]
    lines = [
        f"Trace trail for path {path}",
        "",
        (
            f"{len(results)} committed Trace Patch"
            f"{'' if len(results) == 1 else 'es'} touching this file"
        ),
        "",
    ]
    for index, row in enumerate(results):
        lines.extend(
            _trace_patch_branch_for_path(
                row,
