    skill: str | None,
    tool: str | None,
    files: str | None,
    file_kind: str | None,
    file_op: str | None,
    signal: str | None,
    facet_filters: tuple[str, ...],
    metadata_filters: tuple[str, ...],
    provider: str | None,
    cmd_family: str | None,
